// work.comment.toAction — E5 AC2 "turn into action". Generated by `pnpm gen:command`; guard cases kept,
// acceptance cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { aStaffActor, countRows } from '@ocs/testing';
import { Forbidden, NotFound, ValidationFailed } from '../../kernel/index.ts';
import { addComment } from '../commands/add-comment.ts';
import { commentToAction } from '../commands/comment-to-action.ts';
import { openWorkWorld, type WorkWorld } from './fixture.ts';

const pm = aStaffActor({ roles: ['pm'] });
const sales = aStaffActor({ roles: ['sales'] });
let w: WorkWorld;
let commentId: string;

beforeAll(async () => {
  w = await openWorkWorld();
  w.t.grant(pm, addComment.permission, commentToAction.permission);
  w.t.grant(sales, addComment.permission);
  ({ id: commentId } = await w.t.kernel.execute(
    addComment,
    sales,
    { siteId: w.siteId, body: 'Client IT to send the floor plan before the survey' },
    'test',
  ));
});

afterAll(async () => {
  await w.close();
});

describe('work.comment.toAction', () => {
  it('refuses an actor without the permission', async () => {
    await expect(
      w.t.kernel.execute(
        commentToAction,
        sales,
        { commentId, owner: { userId: sales.id }, due: '2026-11-13' },
        'test',
      ),
    ).rejects.toBeInstanceOf(Forbidden);
  });

  it('needs an owner and a due date (SOP-DEL-03), and a comment that exists', async () => {
    await expect(
      w.t.kernel.execute(commentToAction, pm, { commentId, due: '2026-11-13' }, 'test'),
    ).rejects.toBeInstanceOf(ValidationFailed);
    await expect(
      w.t.kernel.execute(
        commentToAction,
        pm,
        { commentId: randomUUID(), owner: { name: 'Person A' }, due: '2026-11-13' },
        'test',
      ),
    ).rejects.toBeInstanceOf(NotFound);
  });

  it('creates an action on the same project, linked to the comment, titled from it by default', async () => {
    const { id } = await w.t.kernel.execute(
      commentToAction,
      pm,
      { commentId, owner: { name: 'Person A (client IT)' }, due: '2026-11-13' },
      'test',
    );
    expect(
      await countRows(
        w.testDb.url,
        `action WHERE id = $1 AND comment_id = $2 AND source_kind = 'comment' AND site_id = $3
           AND title = 'Client IT to send the floor plan before the survey'`,
        [id, commentId, w.siteId],
      ),
    ).toBe(1);
  });
});
